    arb__json_begin(&j, body, sizeof(body));
    arb__json_key(&j, "name");
    arb__json_bytes(&j, (const uint8_t *)name, strlen(name));
    blen = arb__json_end(&j);

    rc = arb__request_ok(c, ARB_ACT_PURGE_STREAM, body, (uint32_t)blen, &rep);
    if (rc == ARBITRO_OK && rep && out_purged && rep->rep_len >= 8)
        *out_purged = arb__get_u64(rep->rep_buf);
    if (rep) arb__pending_release(rep);
    return rc;
